<script setup lang="ts">
import { computed } from 'vue';
import { X,Upload,CircleCheck,CircleAlert,Pause,FileCheck,LoaderCircle,ArrowRight,FileUp } from '@lucide/vue';
import { desk,safely,checkUploads,commitUploads,discardTask,cancelUpload,openView,recheckJob,cancelJob,dismissJob } from './store';
import {backendTaskFinished,backendTaskNeedsReview,backendTaskLabels,backendTaskName} from './backend-tasks';
import { bytes,taskFinished,imported,type Task } from './model';
const ready=computed(()=>desk.tasks.filter(t=>t.state==='review').length);
const queued=computed(()=>desk.tasks.some(t=>['queued','error','unknown','expired','needs-file','check-error'].includes(t.state)));
const done=computed(()=>desk.tasks.filter(imported).length);
const labels:Record<string,string>={queued:'等待检查',uploading:'上传中',checking:'检查中',review:'等待确认',importing:'导入中',done:'已导入',error:'需要重试',skipped:'已跳过',unknown:'结果待确认',expired:'暂存过期',undone:'已撤销',
'needs-file':'需要重新选择文件','check-error':'已导入，检查未通过'};
const summary=computed(()=>[`${desk.tasks.length} 项`,ready.value?`${ready.value} 项等待确认`:'',done.value?`${done.value} 项已导入`:''].filter(Boolean).join(' · '));
function review(){desk.tasksOpen=false;safely(()=>openView('changes','changes'));}
</script>
<template><section class="task-card" role="dialog" aria-label="导入清单">
 <header class="card-header"><span class="header-icon"><FileUp :size="17"/></span><div><strong>任务与导入清单</strong><small>{{summary||'选择或拖入文件后，先检查，再确认导入'}}</small></div><button class="text-action" :disabled="desk.uploading||!desk.tasks.some(taskFinished)" @click="desk.tasks=desk.tasks.filter(t=>!taskFinished(t))">清除完成项</button><button class="icon-button" aria-label="收起导入清单" title="收起" @click="desk.tasksOpen=false"><X :size="16"/></button></header>
 <div class="task-list"><article v-for="job in desk.jobs.filter(j=>!j.dismissed).slice(0,30)" :key="job.id" class="backend-task"><span class="task-symbol"><CircleCheck v-if="job.state==='SUCCEEDED'" :size="18"/><CircleAlert v-else-if="backendTaskNeedsReview(job)||job.state==='FAILED'" :size="18"/><LoaderCircle v-else-if="!backendTaskFinished(job)" class="spin" :size="18"/></span><div class="task-copy"><strong>{{backendTaskName(job)}}{{job.projectId?` · ${job.projectId}`:''}}</strong><small>{{job.phase}} · {{job.id.slice(0,8)}}</small><small v-if="job.error" class="error-copy">{{job.error}}</small></div><span>{{backendTaskLabels[job.state]}}</span><button v-if="!backendTaskFinished(job)" @click="safely(()=>recheckJob(job.id))">复查结果</button><button v-if="job.state==='QUEUED'" @click="safely(()=>cancelJob(job))">取消排队</button><button v-if="backendTaskNeedsReview(job)" @click="dismissJob(job)">已核对，移出提示</button><button v-if="backendTaskFinished(job)" class="icon-button" aria-label="移出已完成任务提示" @click="job.dismissed=true"><X :size="14"/></button></article><article v-for="task in desk.tasks" :key="task.id" :class="task.state">
  <span class="task-symbol"><CircleCheck v-if="imported(task)||task.state==='skipped'" :size="18"/><CircleAlert v-else-if="task.state==='error'" :size="18"/><LoaderCircle v-else-if="task.state==='uploading'||task.state==='importing'" class="spin" :size="18"/><Upload v-else :size="17"/></span>
  <div class="task-copy"><strong :title="task.name">{{task.name}}</strong><input v-if="task.state==='queued'||task.state==='error'" v-model="task.path" aria-label="保存路径" title="保存到整合包中的路径"><small v-else :title="task.path">{{task.path}}</small><small v-if="task.error" class="error-copy">{{task.error}}</small><small v-else-if="task.plan?.metadata">{{task.plan.metadata.displayName||task.plan.metadata.componentId}} · {{task.plan.metadata.version}}</small><small v-if="task.plan?.replacements?.length" class="task-note">将归档旧模组：{{task.plan.replacements.map((p:any)=>p.path).join('、')}}</small></div>
  <span class="task-size tabular">{{bytes(task.size)}}</span>
  <div class="task-state"><select v-if="task.state==='review'" v-model="task.action" aria-label="导入动作"><option v-if="!task.plan?.existing&&!task.plan?.replacements?.length" value="ADD">新增</option><option v-if="task.plan?.existing&&!task.plan?.replacements?.length" value="OVERWRITE">归档后覆盖</option><option v-if="task.plan?.replacements?.length" value="REPLACE_MOD">替换旧模组</option><option value="SKIP">跳过</option></select><span v-else class="state-label">{{labels[task.state]}}</span><progress v-if="task.state==='uploading'" :value="task.progress" max="100"/></div>
  <button v-if="!desk.uploading" class="icon-button" :aria-label="`移出清单 ${task.name}`" title="移出清单" @click="safely(()=>discardTask(task))"><X :size="14"/></button>
 </article><div v-if="!desk.tasks.length&&!desk.jobs.some(j=>!j.dismissed)" class="empty-task"><Upload :size="22"/><span>选择或拖入文件后，先检查，再确认导入。</span></div></div>
 <footer class="card-footer"><span>导入完成后，到“改动与版本”检查并发布。</span><button v-if="done&&!ready&&!queued&&!desk.uploading" @click="review">检查并发布<ArrowRight :size="14"/></button><button v-if="desk.uploading" @click="desk.uploadPaused=true"><Pause :size="14"/>暂停后续任务</button><button v-if="desk.uploading" @click="cancelUpload">取消当前上传</button><button v-else :disabled="!queued" @click="safely(checkUploads)"><FileCheck :size="15"/>上传并检查</button><button class="accent" :disabled="!ready||desk.uploading" @click="safely(commitUploads)">确认导入{{ready?` ${ready} 项`:''}}</button></footer>
</section></template>
